\boxed{\frac{m}{m_{1}} \sqrt{\frac{G M_{\mathrm{m}}}{R}} - \frac{m - m_{1}}{m_{1}} \sqrt{\frac{2 G M_{\mathrm{m}} R_{\mathrm{m}}}{R\left(R + R_{\mathrm{m}}\right)}}}

