    \end{pmatrix}.
\end{align*}
The quantum relative entropy is defined by
\begin{equation*}
D(\rho||\sigma)= \begin{cases}
 \mathrm{tr}\Big(\rho\big(\log(\rho)-\log(\sigma)\big)\Big) &\text{ if } \text{supp}(\rho)\subseteq \text{supp}(\sigma), \\
\infty &\text{ else}.
\end{cases}
\end{equation*}


